#include <deque>
#include <algorithm>

int main() {
    std::deque<int> d = {1, 2, 3, 4, 5};

    for (auto it = d.begin(); it != d.end(); ) {
        if (*it % 2 != 0) { // If odd, erase it
            // Capture the return value (the iterator to the next element)
            it = d.erase(it); 
        } else {
            // If not erased, move to the next element safely
            ++it;
        }
    }
    // d now contains: {2, 4}
}
